using WAID.EventAnalysis;using WAID.Infrastructure.Persistence;namespace WAID.Infrastructure.Tests;public sealed class EvidenceGraphPersistenceTests{[Fact]public async Task Graph_round_trip_preserves_nodes_edges_provenance_confidence_and_versions(){var path=Path.Combine(Path.GetTempPath(),$"waid-graph-{Guid.NewGuid():N}.db");try{var db=new WaidDatabase($"Data Source={path};Pooling=False");await db.InitializeAsync(CancellationToken.None);var now=DateTimeOffset.UtcNow;var nodeA=new EvidenceNode("a",EvidenceDomain.Event,"POWER","Power",now,now,EvidenceFreshness.Current,new Dictionary<string,string>(),[new("event","scanner","event:41","1")],0);var nodeB=new EvidenceNode("b",EvidenceDomain.Storage,"SMART","Disk",now,now,EvidenceFreshness.Current,new Dictionary<string,string>(),[new("disk","scanner","smart","1")],0);var edge=new EvidenceRelationship("e","a","b",EvidenceRelationshipKind.CausalCandidate,.6,"temporal","v1","within window",false);var graph=new EvidenceGraph(Guid.NewGuid(),now,"1.0","v1",[nodeA,nodeB],[edge],now.AddDays(90));var repo=new SqliteEvidenceGraphRepository(db);await repo.SaveAsync(graph,CancellationToken.None);var loaded=await repo.GetLatestAsync(CancellationToken.None);Assert.Equal(graph.Id,loaded!.Id);Assert.Equal("event:41",loaded.Nodes[0].Provenance[0].SourceReference);Assert.Equal(.6,Assert.Single(loaded.Relationships).Confidence);Assert.False(loaded.Relationships[0].IsCausalClaim);Assert.Equal("v1",loaded.StrategyVersion);}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}}}